#!/usr/bin/env bash
# Generates the Phase 13 validation dataset (05-IMPLEMENTATION-PLAN.md) using a synthetic,
# license-clean source instead of copyrighted music, so it can be committed and regenerated by
# anyone. Requires ffmpeg with libmp3lame (brew install ffmpeg).
set -euo pipefail

cd "$(dirname "$0")/.."
REF=reference
DURATION=12
RATE=44100

command -v ffmpeg >/dev/null || { echo "ffmpeg not found. brew install ffmpeg" >&2; exit 1; }

mkdir -p "$REF"/{original,mp3-320,mp3-256,mp3-192,mp3-128,transcoded-128-to-320,transcoded-192-to-320,problematic-mastering,low-loudness}

echo "== Synthesizing full-bandwidth original =="
# A few tonal components (bass/mid/high) plus pink noise for real high-frequency content, so a
# low-bitrate encoder's lowpass filter has something genuine to cut. loudnorm targets -14 LUFS,
# typical streaming-master loudness, so the plain bitrate ladder below lands on "GOOD X KBPS"
# rather than every file defaulting into the "LOW LOUDNESS" verdict branch (an earlier, quieter
# revision of this source did exactly that — a dataset-generation bug caught by running the
# full ladder through the analyzer and noticing every single verdict came back the same).
ffmpeg -y -loglevel error \
  -f lavfi -i "sine=frequency=110:duration=${DURATION}:sample_rate=${RATE}" \
  -f lavfi -i "sine=frequency=440:duration=${DURATION}:sample_rate=${RATE}" \
  -f lavfi -i "sine=frequency=2000:duration=${DURATION}:sample_rate=${RATE}" \
  -f lavfi -i "anoisesrc=duration=${DURATION}:color=pink:sample_rate=${RATE}:amplitude=0.18" \
  -filter_complex "[0:a]volume=0.25[a0];[1:a]volume=0.20[a1];[2:a]volume=0.15[a2];[3:a]volume=1.0[a3];\
[a0][a1][a2][a3]amix=inputs=4:duration=longest:normalize=0,tremolo=f=0.2:d=0.3,aformat=channel_layouts=stereo,loudnorm=I=-14:TP=-1:LRA=7" \
  -ar "$RATE" -sample_fmt s16 "$REF/original/track-original.wav"

echo "== Encoding bitrate ladder =="
for kbps in 320 256 192 128; do
  ffmpeg -y -loglevel error -i "$REF/original/track-original.wav" \
    -codec:a libmp3lame -b:a "${kbps}k" \
    "$REF/mp3-$kbps/track-$kbps.mp3"
done

echo "== Building transcodes (decode then re-encode at a higher declared bitrate) =="
ffmpeg -y -loglevel error -i "$REF/mp3-128/track-128.mp3" \
  -codec:a libmp3lame -b:a 320k \
  "$REF/transcoded-128-to-320/track-128-transcoded-320.mp3"

ffmpeg -y -loglevel error -i "$REF/mp3-192/track-192.mp3" \
  -codec:a libmp3lame -b:a 320k \
  "$REF/transcoded-192-to-320/track-192-transcoded-320.mp3"

echo "== Building problematic-mastering case (clean 320kbps encode of a hard-clipped source) =="
# No limiter: ffmpeg hard-clips samples that exceed full scale when converting to PCM, which is
# exactly the sustained-clipping / heavily-limited signature poor mastering leaves behind. A first
# attempt used alimiter here, which is a *transparent* limiter by design — it prevented the very
# clipping this test case needs, so mastering score came back 90/100 instead of flagging anything.
ffmpeg -y -loglevel error -i "$REF/original/track-original.wav" \
  -filter:a "volume=20dB" \
  -codec:a libmp3lame -b:a 320k \
  "$REF/problematic-mastering/track-mastering-issues-320.mp3"

echo "== Building low-loudness case (clean 320kbps encode, quiet but undamaged) =="
ffmpeg -y -loglevel error -i "$REF/original/track-original.wav" \
  -filter:a "volume=-22dB" \
  -codec:a libmp3lame -b:a 320k \
  "$REF/low-loudness/track-low-loudness-320.mp3"

echo "Done. Dataset written to $REF/"
